import{R as e,e as a,f as n,U as o}from"./chunks/framework.ywem4qy5.js";const y=JSON.parse('{"title":"Westpac PayWay","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/payments/payway.md","filePath":"integrations/payments/payway.md","lastUpdated":1775908585000}'),i={name:"integrations/payments/payway.md"};function r(s,t,l,c,h,g){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="westpac-payway" tabindex="-1">Westpac PayWay <a class="header-anchor" href="#westpac-payway" aria-label="Permalink to &quot;Westpac PayWay&quot;">​</a></h1><p>Follow the below steps to connect to the Westpac PayWay API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Payments</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Westpac PayWay</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-westpac-payway-api" tabindex="-1">Step 2. Connect to the Westpac PayWay API <a class="header-anchor" href="#step-2-connect-to-the-westpac-payway-api" aria-label="Permalink to &quot;Step 2. Connect to the Westpac PayWay API&quot;">​</a></h3><ol><li>Go to your <a href="https://www.payway.com.au/" target="_blank">PayWay account</a>.</li><li>Click on the <strong>Settings</strong> navigation item in the top-right of the main header navigation.</li><li>Click the <strong>REST API Keys</strong> link.</li><li>Click the <strong>Add</strong> button, and select <strong>Publishable</strong> as the API Key type. Click the <strong>Save</strong> button.</li><li>Copy the <strong>API Key</strong> from Westpac PayWay and paste in the <strong>Publishable Key</strong> field in Formie.</li><li>Go back and click the click the <strong>Add</strong> button, and select <strong>Secret</strong> as the API Key type. Click the <strong>Save</strong> button.</li><li>Copy the <strong>API Key</strong> from Westpac PayWay and paste in the <strong>Secret Key</strong> field in Formie.</li><li>Click on the <strong>Settings</strong> navigation item in the top-right of the main header navigation.</li><li>Click the <strong>Merchants</strong> link.</li><li>Copy the <strong>Merchant ID</strong> from Westpac PayWay and paste in the <strong>Merchant ID</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-field-setting" tabindex="-1">Step 4. Field Setting <a class="header-anchor" href="#step-4-field-setting" aria-label="Permalink to &quot;Step 4. Field Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Add a <strong>Payment</strong> field to your form.</li><li>Select Westpac PayWay for the <strong>Payment Provider</strong>.</li></ol><p>The Westpac PayWay payment integration supports only once-off payments.</p>',11)])])}const d=e(i,[["render",r]]);export{y as __pageData,d as default};
